namespace UnrealCode.ComputerFixture;
internal static class Program {
 [STAThread] static void Main(){ApplicationConfiguration.Initialize();var form=new Form{Text="UnrealCode disposable computer fixture",Width=680,Height=480,StartPosition=FormStartPosition.CenterScreen};var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(24),WrapContents=false};var title=new Label{Text="Computer acceptance fixture",AutoSize=true,Font=new Font("Segoe UI",18)};var text=new TextBox{AccessibleName="Draft note",Multiline=true,Width=590,Height=140,Text="Initial fixture text"};var password=new TextBox{AccessibleName="Password",UseSystemPasswordChar=true,Text="fixture-only-password",Width=280};var status=new Label{AccessibleName="Fixture result",Text="No artifact saved",AutoSize=true};var save=new Button{Text="Save fixture artifact",AccessibleName="Save fixture artifact",AutoSize=true};save.Click+=(_,_)=>{File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"result.txt"),text.Text);status.Text="Artifact saved and verified: "+text.Text;};var modal=new Button{Text="Open test dialog",AutoSize=true};modal.Click+=(_,_)=>MessageBox.Show(form,"Unexpected fixture dialog. Close it yourself before handback.","Fixture dialog");panel.Controls.AddRange([title,text,new Label{Text="Dummy credential field for redaction",AutoSize=true},password,save,modal,status]);form.Controls.Add(panel);Application.Run(form);}
}
